<?php
require_once __DIR__.'/portal.php';
function rmmc_staff_students(string $role): void {
    rmmc_require_roles($role);
    $search=trim((string)($_GET['search']??'')); $course=trim((string)($_GET['course']??''));$year=trim((string)($_GET['year']??''));
    $where=['1=1'];$params=[];$types='';
    if ($search!==''){ $where[]='(student_number LIKE ? OR firstname LIKE ? OR lastname LIKE ?)';$v='%'.$search.'%';array_push($params,$v,$v,$v);$types.='sss'; }
    if ($course!==''){ $where[]='UPPER(TRIM(course)) = ?';$params[]=strtoupper($course);$types.='s'; }
    if ($year!==''){ $where[]='year_level = ?';$params[]=$year;$types.='s'; }
    $page=max(1,min(99999,(int)($_GET['page']??1)));$limit=25;$offset=($page-1)*$limit;
    $filter=implode(' AND ',$where);
    $count=(int)(rmmc_one("SELECT COUNT(*) n FROM students WHERE $filter",$types,$params)['n']??0);
    $rows=rmmc_all("SELECT id,student_number,firstname,lastname,course,year_level FROM students WHERE $filter ORDER BY lastname,firstname LIMIT ? OFFSET ?",$types.'ii',array_merge($params,[$limit,$offset]));
    $courses=rmmc_all('SELECT DISTINCT UPPER(TRIM(course)) name FROM students ORDER BY name');$years=rmmc_all('SELECT DISTINCT year_level name FROM students ORDER BY year_level');
    rmmc_shell_start('Students',$role);
    ?><div class="welcome"><h1>Enrolled students</h1><p>Search and filter student records, then select a student to inspect attendance, fines, and QR details.</p></div><section class="panel"><form method="get" class="filters"><div class="field"><label for="search">Name or Student ID</label><input id="search" name="search" value="<?=rmmc_e($search)?>" placeholder="Find a student"></div><div class="field"><label for="course">Course</label><select id="course" name="course"><option value="">All courses</option><?php foreach($courses as $c):?><option value="<?=rmmc_e($c['name'])?>" <?=$course===$c['name']?'selected':''?>><?=rmmc_e($c['name'])?></option><?php endforeach;?></select></div><div class="field"><label for="year">Year level</label><select id="year" name="year"><option value="">All year levels</option><?php foreach($years as $y):?><option value="<?=rmmc_e($y['name'])?>" <?=$year===$y['name']?'selected':''?>><?=rmmc_e($y['name'])?></option><?php endforeach;?></select></div><button>Apply filters</button><a href="students.php" class="btn ghost">Reset</a></form><p class="small">Showing <?=count($rows)?> of <?=number_format($count)?> matching students</p><div class="table-scroll"><table class="data-table"><thead><tr><th>Student ID</th><th>Full name</th><th>Course</th><th>Year</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=rmmc_e($r['student_number'])?></td><td><?=rmmc_e($r['lastname'].', '.$r['firstname'])?></td><td><?=rmmc_e($r['course'])?></td><td><?=rmmc_e($r['year_level'])?></td><td><a href="student_view.php?id=<?=(int)$r['id']?>">View profile →</a></td></tr><?php endforeach;?></tbody></table></div><?php if(!$rows): ?><p class="empty">No matching students found.</p><?php endif; ?><div class="row" style="margin-top:18px"><?php $q=http_build_query(['search'=>$search,'course'=>$course,'year'=>$year]); if ($page>1): ?><a class="btn ghost" href="?<?=$q?>&page=<?=$page-1?>">← Previous</a><?php endif; ?><?php if($count>$page*$limit):?><a class="btn ghost" href="?<?=$q?>&page=<?=$page+1?>">Next →</a><?php endif;?></div></section><?php rmmc_shell_end();
}
function rmmc_staff_student_view(string $role): void {
    rmmc_require_roles($role);
    $sid=(int)($_GET['id']??0);
    $st=rmmc_one('SELECT * FROM students WHERE id=?','i',[$sid]);
    if(!$st){ http_response_code(404);exit('Student not found'); }
    $history=rmmc_all('SELECT a.*,e.title FROM attendance a JOIN events e ON a.event_id=e.id WHERE a.student_id=? ORDER BY a.date DESC LIMIT 50','i',[$sid]);
    $fines=rmmc_table_exists('ite_event_fines') ? rmmc_all('SELECT f.*,e.title,(SELECT COALESCE(SUM(p.amount),0) FROM ite_fine_payments p WHERE p.fine_id=f.id) paid FROM ite_event_fines f JOIN events e ON e.id=f.event_id WHERE f.student_id=? ORDER BY f.created_at DESC','i',[$sid]) : [];
    rmmc_shell_start('Student Profile',$role);
    ?><p><a href="students.php">← Back to student list</a></p><section class="id-card"><div class="avatar"><?=rmmc_e(strtoupper(substr((string)$st['firstname'],0,1)))?></div><div class="id-details"><h2><?=rmmc_e($st['lastname'].', '.$st['firstname'])?></h2><p>ID: <?=rmmc_e($st['student_number'])?></p><p><?=rmmc_e($st['course'])?> · <?=rmmc_e($st['year_level'])?></p></div><span class="pill">Student</span></section><div class="panel"><h2>Event attendance</h2><div class="table-scroll"><table class="data-table"><tr><th>Event</th><th>Date</th><th>Morning in/out</th><th>Afternoon in/out</th><th>Status</th></tr><?php foreach($history as $h): ?><tr><td><?=rmmc_e($h['title'])?></td><td><?=rmmc_e($h['date'])?></td><td><?=rmmc_e($h['morning_in'])?> / <?=rmmc_e($h['morning_out'])?></td><td><?=rmmc_e($h['afternoon_in'])?> / <?=rmmc_e($h['afternoon_out'])?></td><td><?=rmmc_badge((string)$h['status'])?></td></tr><?php endforeach;?></table></div><?php if(!$history):?><p class="empty">No attendance history available.</p><?php endif;?></div><div class="panel"><h2>Event fines and payments</h2><div class="table-scroll"><table class="data-table"><tr><th>Event</th><th>Reason</th><th>Fine</th><th>Paid</th><th>Outstanding</th></tr><?php foreach($fines as $f): ?><tr><td><?=rmmc_e($f['title'])?></td><td><?=rmmc_e($f['reason'])?></td><td>₱<?=number_format((float)$f['amount'],2)?></td><td>₱<?=number_format((float)$f['paid'],2)?></td><td>₱<?=number_format(max(0,(float)$f['amount']-(float)$f['paid']),2)?></td></tr><?php endforeach;?></table></div><?php if(!$fines):?><p class="empty">No event fines recorded in the upgraded ledger.</p><?php endif;?></div><?php rmmc_shell_end();
}
